import discordfrom discord import Colorfrom discord.ext import commandsfrom utils.EmbedGeneratorUtil import EmbedGeneratorfrom utils.custom.errors.FingerBangThePoonTangBotError import BotAlreadyInChannelErrorclass OnCommandError(commands.Cog):    def __init__(self, bot: commands.Bot):        self.bot = bot    @commands.Cog.listener()    async def on_command_error(self, ctx: discord.ext.commands.Context, error: discord.ext.commands.CommandError):        """        Runs if any of the commands/events errors are not already caught, throw an error.        :param ctx: This is the discord Interaction we can access data from        :param error: This is the error message that is thrown whenever the error is thrown.        :return:        """        if isinstance(error, commands.NoPrivateMessage):            embed = EmbedGenerator(self.bot).generate_title_message_embed_with_footer(title="📛 An Error Has Occurred 📛", description="This command can not be used in private messages.", colour=Color.red(), timestamp=True)            await ctx.author.send(embed=embed)        elif isinstance(error, commands.MissingRole):            embed = EmbedGenerator(self.bot).generate_title_message_embed_with_footer(title="📛 An Error Has Occurred 📛", description="You are missing the required role to perform this command.", colour=Color.red(), timestamp=True)            await ctx.reply(embed=embed, ephemeral=True)        elif isinstance(error, commands.BotMissingRole):            embed = EmbedGenerator(self.bot).generate_title_message_embed_with_footer(title="📛 An Error Has Occurred 📛", description="I am missing the required role to perform this command.", colour=Color.red(), timestamp=True)            await ctx.reply(embed=embed, ephemeral=True)        elif isinstance(error, commands.MissingPermissions):            embed = EmbedGenerator(self.bot).generate_title_message_embed_with_footer(title="📛 An Error Has Occurred 📛", description=f"You are missing the required permissions to perform this command.", colour=Color.red(), timestamp=True)            await ctx.reply(embed=embed, ephemeral=True)        elif isinstance(error, commands.BotMissingPermissions):            embed = EmbedGenerator(self.bot).generate_title_message_embed_with_footer(title="📛 An Error Has Occurred 📛", description="I am missing the required permissions to perform this command.", colour=Color.red(), timestamp=True)            await ctx.reply(embed=embed, ephemeral=True)        elif isinstance(error, commands.CommandNotFound):            embed = EmbedGenerator(self.bot).generate_title_message_embed_with_footer(title="📛 An Error Has Occurred 📛", description="That command does not exist! Please try again.", colour=Color.red(), timestamp=True)            await ctx.reply(embed=embed, ephemeral=True)        elif isinstance(error, commands.MissingRequiredArgument):            embed = EmbedGenerator(self.bot).generate_title_message_embed_with_footer(title="📛 An Error Has Occurred 📛", description=f"You are missing a required argument!  \n{error.param.name}: {error.param.description}", colour=Color.red(), timestamp=True)            await ctx.reply(embed=embed, ephemeral=True)        elif isinstance(error, commands.CommandInvokeError):            original_error = getattr(error, 'original', error)            embed = EmbedGenerator(self.bot).generate_title_message_embed_with_footer(title="📛 A Command Error Has Occurred 📛", description=f"{original_error}", colour=Color.red(), timestamp=True)            await ctx.reply(embed=embed, ephemeral=True)        elif isinstance(error, BotAlreadyInChannelError):            embed = EmbedGenerator(self.bot).generate_title_message_embed_with_footer(title="📛 A Command Error Has Occurred 📛", description=f"{error}", colour=Color.red(), timestamp=True)            await ctx.reply(embed=embed, ephemeral=True)        else:            embed = EmbedGenerator(self.bot).generate_title_message_embed_with_footer(title="📛 An UNKNOWN Error Has Occurred 📛", description=f"{error}", colour=Color.red(), timestamp=True)            await ctx.reply(embed=embed, ephemeral=True)async def setup(bot: commands.Bot):    await bot.add_cog(OnCommandError(bot))